// Generated by `dart run drift_dev make-migrations`, then completed by hand:
// each new schema version adds its case here, with real data.
import 'package:drift/drift.dart';
import 'package:drift_dev/api/migrations_native.dart';
import 'package:flutter_test/flutter_test.dart';
import 'package:kibuo/data/database.dart';

import 'generated/schema.dart';
import 'generated/schema_v1.dart' as v1;
import 'generated/schema_v10.dart' as v10;
import 'generated/schema_v11.dart' as v11;
import 'generated/schema_v12.dart' as v12;
import 'generated/schema_v13.dart' as v13;
import 'generated/schema_v14.dart' as v14;
import 'generated/schema_v2.dart' as v2;
import 'generated/schema_v3.dart' as v3;
import 'generated/schema_v4.dart' as v4;
import 'generated/schema_v5.dart' as v5;
import 'generated/schema_v6.dart' as v6;
import 'generated/schema_v7.dart' as v7;
import 'generated/schema_v8.dart' as v8;
import 'generated/schema_v9.dart' as v9;

KibuoDatabase _open(QueryExecutor e) => KibuoDatabase(e, deviceId: 'phone-1');

void main() {
  driftRuntimeOptions.dontWarnAboutMultipleDatabases = true;
  late SchemaVerifier verifier;

  setUpAll(() {
    verifier = SchemaVerifier(GeneratedHelper());
  });

  group('simple database migrations', () {
    // These simple tests verify all possible schema updates with a simple (no
    // data) migration. This is a quick way to ensure that written database
    // migrations properly alter the schema.
    const versions = GeneratedHelper.versions;
    for (final (i, fromVersion) in versions.indexed) {
      group('from $fromVersion', () {
        for (final toVersion in versions.skip(i + 1)) {
          test('to $toVersion', () async {
            final schema = await verifier.schemaAt(fromVersion);
            final db = _open(schema.newConnection());
            await verifier.migrateAndValidate(db, toVersion);
            await db.close();
          });
        }
      });
    }
  });

  test(
    'version 1 to 2 keeps the devices and adds the currency tables',
    () async {
      const phone = v1.DevicesData(
        id: 'phone-1',
        version: 42,
        deviceId: 'phone-1',
        deleted: 0,
      );

      await verifier.testWithDataIntegrity(
        oldVersion: 1,
        newVersion: 2,
        createOld: v1.DatabaseAtV1.new,
        createNew: v2.DatabaseAtV2.new,
        openTestedDatabase: _open,
        createItems: (batch, oldDb) => batch.insert(oldDb.devices, phone),
        validateItems: (newDb) async {
          expect(await newDb.select(newDb.devices).get(), const [
            v2.DevicesData(
              id: 'phone-1',
              version: 42,
              deviceId: 'phone-1',
              deleted: 0,
            ),
          ]);
          expect(await newDb.select(newDb.currencies).get(), isEmpty);
          expect(await newDb.select(newDb.exchangeRates).get(), isEmpty);
        },
      );
    },
  );

  test('version 2 to 3 keeps currencies and rates, adds accounts', () async {
    const euro = v2.CurrenciesData(
      id: 'cur-1',
      version: 50,
      deviceId: 'phone-1',
      deleted: 0,
      code: 'EUR',
      usesDecimals: 1,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 2,
      newVersion: 3,
      createOld: v2.DatabaseAtV2.new,
      createNew: v3.DatabaseAtV3.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.currencies, euro),
      validateItems: (newDb) async {
        expect(await newDb.select(newDb.currencies).get(), const [
          v3.CurrenciesData(
            id: 'cur-1',
            version: 50,
            deviceId: 'phone-1',
            deleted: 0,
            code: 'EUR',
            usesDecimals: 1,
          ),
        ]);
        expect(await newDb.select(newDb.accounts).get(), isEmpty);
        expect(await newDb.select(newDb.accountTypes).get(), isEmpty);
      },
    );
  });

  test('version 3 to 4 keeps the accounts, adds categories', () async {
    const account = v3.AccountsData(
      id: 'acc-1',
      version: 60,
      deviceId: 'phone-1',
      deleted: 0,
      name: 'M-Pesa',
      type: 'mobile',
      currency: 'USD',
      openingBalance: 12000,
      openingDate: 1793750400,
      archived: 0,
      position: 1,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 3,
      newVersion: 4,
      createOld: v3.DatabaseAtV3.new,
      createNew: v4.DatabaseAtV4.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.accounts, account),
      validateItems: (newDb) async {
        expect(
          (await newDb.select(newDb.accounts).get()).single.name,
          'M-Pesa',
        );
        expect(await newDb.select(newDb.categories).get(), isEmpty);
      },
    );
  });

  test('version 4 to 5 keeps the categories, adds transactions', () async {
    const food = v4.CategoriesData(
      id: 'default-food',
      version: 70,
      deviceId: 'phone-1',
      deleted: 0,
      kind: 'out',
      key: 'food',
      icon: 'forkKnife',
      position: 1,
      removed: 0,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 4,
      newVersion: 5,
      createOld: v4.DatabaseAtV4.new,
      createNew: v5.DatabaseAtV5.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.categories, food),
      validateItems: (newDb) async {
        expect((await newDb.select(newDb.categories).get()).single.key, 'food');
        expect(await newDb.select(newDb.transactions).get(), isEmpty);
      },
    );
  });

  test('version 5 to 6 keeps the operations, adds attachments', () async {
    const taxi = v5.TransactionsData(
      id: 'tx-1',
      version: 80,
      deviceId: 'phone-1',
      deleted: 0,
      kind: 'out',
      accountId: 'acc-1',
      categoryId: 'default-taxi',
      amount: 500,
      currency: 'USD',
      rateTyped: 0,
      converted: 500,
      fees: 0,
      date: 1794700000,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 5,
      newVersion: 6,
      createOld: v5.DatabaseAtV5.new,
      createNew: v6.DatabaseAtV6.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.transactions, taxi),
      validateItems: (newDb) async {
        expect(
          (await newDb.select(newDb.transactions).get()).single.amount,
          500,
        );
        expect(await newDb.select(newDb.attachments).get(), isEmpty);
      },
    );
  });

  test(
    'version 6 to 7 keeps the operations, makes room for transfers',
    () async {
      const taxi = v6.TransactionsData(
        id: 'tx-1',
        version: 80,
        deviceId: 'phone-1',
        deleted: 0,
        kind: 'out',
        accountId: 'acc-1',
        categoryId: 'default-taxi',
        amount: 500,
        currency: 'USD',
        rateTyped: 0,
        converted: 500,
        fees: 0,
        date: 1794700000,
      );

      await verifier.testWithDataIntegrity(
        oldVersion: 6,
        newVersion: 7,
        createOld: v6.DatabaseAtV6.new,
        createNew: v7.DatabaseAtV7.new,
        openTestedDatabase: _open,
        createItems: (batch, oldDb) => batch.insert(oldDb.transactions, taxi),
        validateItems: (newDb) async {
          final kept = (await newDb.select(newDb.transactions).get()).single;
          expect(kept.categoryId, 'default-taxi');
          expect(kept.toAccountId, equals(null));
          // A transfer has no category and a receiving account.
          await newDb
              .into(newDb.transactions)
              .insert(
                const v7.TransactionsData(
                  id: 'tx-2',
                  version: 81,
                  deviceId: 'phone-1',
                  deleted: 0,
                  kind: 'move',
                  accountId: 'acc-1',
                  toAccountId: 'acc-2',
                  amount: 5000,
                  currency: 'USD',
                  rateTyped: 0,
                  converted: 5000,
                  fees: 0,
                  date: 1794700000,
                ),
              );
        },
      );
    },
  );

  test('version 7 to 8 keeps the accounts, without overdraft', () async {
    const account = v7.AccountsData(
      id: 'acc-1',
      version: 60,
      deviceId: 'phone-1',
      deleted: 0,
      name: 'M-Pesa',
      type: 'mobile',
      currency: 'USD',
      openingBalance: 12000,
      openingDate: 1793750400,
      archived: 0,
      position: 1,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 7,
      newVersion: 8,
      createOld: v7.DatabaseAtV7.new,
      createNew: v8.DatabaseAtV8.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.accounts, account),
      validateItems: (newDb) async {
        final kept = (await newDb.select(newDb.accounts).get()).single;
        expect(kept.name, 'M-Pesa');
        expect(kept.overdraftAllowed, 0, reason: 'off for existing accounts');
        expect(kept.overdraftLimit, equals(null));
      },
    );
  });

  test('version 8 to 9 keeps the operations, adds budgets', () async {
    const account = v8.AccountsData(
      id: 'acc-1',
      version: 60,
      deviceId: 'phone-1',
      deleted: 0,
      name: 'M-Pesa',
      type: 'mobile',
      currency: 'USD',
      openingBalance: 12000,
      openingDate: 1793750400,
      archived: 0,
      position: 1,
      overdraftAllowed: 0,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 8,
      newVersion: 9,
      createOld: v8.DatabaseAtV8.new,
      createNew: v9.DatabaseAtV9.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.accounts, account),
      validateItems: (newDb) async {
        expect(
          (await newDb.select(newDb.accounts).get()).single.name,
          'M-Pesa',
        );
        expect(await newDb.select(newDb.budgets).get(), isEmpty);
        await newDb
            .into(newDb.budgets)
            .insert(
              const v9.BudgetsData(
                id: 'b-1',
                version: 90,
                deviceId: 'phone-1',
                deleted: 0,
                categoryId: 'default-food',
                position: 0,
              ),
            );
        await newDb
            .into(newDb.budgetAmounts)
            .insert(
              const v9.BudgetAmountsData(
                id: 'ba-1',
                version: 91,
                deviceId: 'phone-1',
                deleted: 0,
                budgetId: 'b-1',
                fromMonth: 202611,
                amount: 10000,
                currency: 'USD',
              ),
            );
      },
    );
  });

  test(
    'version 9 to 10 keeps the operations, done, and adds recurrences',
    () async {
      const op = v9.TransactionsData(
        id: 'tx-1',
        version: 95,
        deviceId: 'phone-1',
        deleted: 0,
        kind: 'out',
        accountId: 'acc-1',
        categoryId: 'default-taxi',
        amount: 1500,
        currency: 'USD',
        rateTyped: 0,
        converted: 1500,
        fees: 0,
        date: 1794700000,
      );

      await verifier.testWithDataIntegrity(
        oldVersion: 9,
        newVersion: 10,
        createOld: v9.DatabaseAtV9.new,
        createNew: v10.DatabaseAtV10.new,
        openTestedDatabase: _open,
        createItems: (batch, oldDb) => batch.insert(oldDb.transactions, op),
        validateItems: (newDb) async {
          final kept = (await newDb.select(newDb.transactions).get()).single;
          expect(kept.amount, 1500);
          expect(kept.status, 'done', reason: 'existing operations count');
          expect(kept.recurringId, equals(null));
          expect(await newDb.select(newDb.recurringRules).get(), isEmpty);
        },
      );
    },
  );

  test('version 10 to 11 keeps the operations, adds debts', () async {
    const op = v10.TransactionsData(
      id: 'tx-1',
      version: 105,
      deviceId: 'phone-1',
      deleted: 0,
      kind: 'in',
      accountId: 'acc-1',
      categoryId: 'default-salary',
      amount: 40000,
      currency: 'USD',
      rateTyped: 0,
      converted: 40000,
      fees: 0,
      date: 1794700000,
      status: 'draft',
      recurringId: 'rule-1',
      occurrence: 20261125,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 10,
      newVersion: 11,
      createOld: v10.DatabaseAtV10.new,
      createNew: v11.DatabaseAtV11.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.transactions, op),
      validateItems: (newDb) async {
        final kept = (await newDb.select(newDb.transactions).get()).single;
        expect(kept.amount, 40000);
        expect(kept.status, 'draft');
        expect(kept.occurrence, 20261125);
        expect(kept.debtId, equals(null), reason: 'no debt before');
        expect(await newDb.select(newDb.debts).get(), isEmpty);
      },
    );
  });

  test(
    'a version 11 made elsewhere, without debts, gets them at opening',
    () async {
      // A trial build once took the data to 11 with other tables.
      final schema = await verifier.schemaAt(10);
      final raw = schema.rawDatabase..execute('PRAGMA user_version = 11;');
      final db = _open(schema.newConnection());
      expect(raw.userVersion, 11);
      await db
          .into(db.debts)
          .insert(
            DebtsCompanion.insert(
              id: 'debt-1',
              version: 1,
              deviceId: 'phone-1',
              direction: 'owe',
              person: 'Patrick',
              amount: 20000,
              currency: 'USD',
              openedOn: DateTime.utc(2026, 11, 23),
            ),
          );
      expect((await db.select(db.debts).get()).single.person, 'Patrick');
      final columns = await db
          .customSelect("SELECT name FROM pragma_table_info('transactions')")
          .map((r) => r.read<String>('name'))
          .get();
      expect(columns, contains('debt_id'));
      await db.close();
    },
  );

  test('version 11 to 12 keeps the debts, nothing given up', () async {
    const debt = v11.DebtsData(
      id: 'debt-1',
      version: 110,
      deviceId: 'phone-1',
      deleted: 0,
      direction: 'owe',
      person: 'Patrick',
      amount: 50000,
      currency: 'CDF',
      openedOn: 1794700000,
      dueDate: 1795000000,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 11,
      newVersion: 12,
      createOld: v11.DatabaseAtV11.new,
      createNew: v12.DatabaseAtV12.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.debts, debt),
      validateItems: (newDb) async {
        final kept = (await newDb.select(newDb.debts).get()).single;
        expect(kept.person, 'Patrick');
        expect(kept.amount, 50000);
        expect(kept.forgiven, 0);
        expect(kept.forgivenOn, equals(null));
      },
    );
  });

  test('version 12 to 13 keeps the debts, adds projects', () async {
    const debt = v12.DebtsData(
      id: 'debt-1',
      version: 120,
      deviceId: 'phone-1',
      deleted: 0,
      direction: 'owed',
      person: 'Grâce',
      amount: 2000,
      currency: 'CDF',
      openedOn: 1794700000,
      forgiven: 0,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 12,
      newVersion: 13,
      createOld: v12.DatabaseAtV12.new,
      createNew: v13.DatabaseAtV13.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) => batch.insert(oldDb.debts, debt),
      validateItems: (newDb) async {
        expect((await newDb.select(newDb.debts).get()).single.person, 'Grâce');
        expect(await newDb.select(newDb.projects).get(), isEmpty);
        expect(await newDb.select(newDb.contributions).get(), isEmpty);
      },
    );
  });

  test('version 13 to 14 keeps the contributions, with no source', () async {
    const project = v13.ProjectsData(
      id: 'project-1',
      version: 130,
      deviceId: 'phone-1',
      deleted: 0,
      name: 'Voyage',
      icon: 'airplane',
      accountId: 'account-1',
      goal: 30000,
      currency: 'USD',
      startedOn: 1794700000,
      period: 'week',
      remind: 1,
    );
    const contribution = v13.ContributionsData(
      id: 'contribution-1',
      version: 131,
      deviceId: 'phone-1',
      deleted: 0,
      projectId: 'project-1',
      amount: 5000,
      date: 1794800000,
    );

    await verifier.testWithDataIntegrity(
      oldVersion: 13,
      newVersion: 14,
      createOld: v13.DatabaseAtV13.new,
      createNew: v14.DatabaseAtV14.new,
      openTestedDatabase: _open,
      createItems: (batch, oldDb) {
        batch.insert(oldDb.projects, project);
        batch.insert(oldDb.contributions, contribution);
      },
      validateItems: (newDb) async {
        final kept = (await newDb.select(newDb.contributions).get()).single;
        expect(kept.amount, 5000);
        expect(kept.fromAccountId, equals(null));
        expect(
          (await newDb.select(newDb.projects).get()).single.name,
          'Voyage',
        );
      },
    );
  });
}
